// Das Frontend kennt nur EINE Nachrichten-/Werkzeugform (angelehnt an die
// Anthropic Messages API - siehe src/types/agent.ts im Repo). Fuer ChatGPT
// muss das hier ins Chat-Completions-Format von OpenAI uebersetzt werden,
// damit agentClient.ts im Frontend nichts von den Unterschieden zwischen
// den Anbietern wissen muss.

function toOpenAiTools(tools) {
  return (tools || []).map(function (t) {
    return {
      type: "function",
      function: { name: t.name, description: t.description, parameters: t.input_schema }
    };
  });
}

function toOpenAiMessages(messages) {
  const out = [];
  for (const m of messages) {
    if (typeof m.content === "string") {
      out.push({ role: m.role, content: m.content });
      continue;
    }
    if (m.role === "assistant") {
      const textParts = m.content.filter(function (b) { return b.type === "text"; }).map(function (b) { return b.text; });
      const toolCalls = m.content
        .filter(function (b) { return b.type === "tool_use"; })
        .map(function (b) {
          return { id: b.id, type: "function", function: { name: b.name, arguments: JSON.stringify(b.input) } };
        });
      const assistantMsg = { role: "assistant", content: textParts.join("\n") || null };
      if (toolCalls.length) assistantMsg.tool_calls = toolCalls;
      out.push(assistantMsg);
    } else {
      // OpenAI verlangt PRO Tool-Ergebnis eine eigene "tool"-Nachricht,
      // anders als Anthropic, das mehrere tool_result-Bloecke in EINER
      // User-Nachricht buendelt.
      const toolResults = m.content.filter(function (b) { return b.type === "tool_result"; });
      if (toolResults.length) {
        for (const tr of toolResults) {
          out.push({ role: "tool", tool_call_id: tr.tool_use_id, content: tr.content });
        }
      } else {
        const text = m.content.filter(function (b) { return b.type === "text"; }).map(function (b) { return b.text; }).join("\n");
        out.push({ role: "user", content: text });
      }
    }
  }
  return out;
}

const messages = msg.clientMessages ?? [{ role: "user", content: msg.user_prompt }];
const systemText = "Antwortsprache: " + msg.locale + ". Antworte ausschließlich in dieser Sprache." + msg.system_prompt;

msg.headers = {
  "Content-Type": "application/json",
  "Authorization": "Bearer " + msg.openai_api_key
};

msg.payload = {
  model: env.get("OPENAI_MODEL") || "gpt-4o",
  messages: [{ role: "system", content: systemText }].concat(toOpenAiMessages(messages))
};

const openaiTools = toOpenAiTools(msg.tools);
if (openaiTools.length) {
  msg.payload.tools = openaiTools;
  // Ohne tool_choice faellt ChatGPT auf "auto" zurueck und erzaehlt den
  // Bauplan gerne einfach als Freitext mit eingebettetem JSON-Codeblock,
  // statt ihn ueber einen echten Funktionsaufruf zurueckzugeben - das
  // Frontend (agentClient.ts) sucht aber gezielt nach einem tool_use-Block
  // und baut sonst gar nichts. "required" zwingt zu einem echten Aufruf
  // eines der uebergebenen Tools (hier: build_plan).
  msg.payload.tool_choice = "required";
}

return msg;

// Wandelt die OpenAI-Chat-Completions-Antwort in dieselbe Form um, die der
// Claude-Pfad liefert ({content: [...], stop_reason, usage}) - das
// Frontend (agentClient.ts) braucht dadurch nie zu wissen, welcher Anbieter
// tatsaechlich geantwortet hat.
let res = msg.payload;

if (res && res.error) {
  msg.statusCode = 502;
  msg.payload = { error: res.error.message || "Unbekannter Fehler von ChatGPT" };
  msg.raw = msg.payload.error;
  return msg;
}

const choice = res && res.choices && res.choices[0];
if (!choice) {
  msg.statusCode = 502;
  msg.payload = { error: "Unerwartete Antwortform von ChatGPT" };
  msg.raw = msg.payload.error;
  return msg;
}

const openaiMsg = choice.message || {};
const content = [];
if (openaiMsg.content) content.push({ type: "text", text: openaiMsg.content });
for (const tc of (openaiMsg.tool_calls || [])) {
  let input = {};
  try { input = JSON.parse(tc.function.arguments); } catch (e) {}
  content.push({ type: "tool_use", id: tc.id, name: tc.function.name, input: input });
}

const stopReasonMap = { stop: "end_turn", tool_calls: "tool_use", length: "max_tokens", content_filter: "refusal" };

msg.statusCode = 200;
msg.payload = {
  content: content,
  stop_reason: stopReasonMap[choice.finish_reason] || choice.finish_reason || null,
  usage: res.usage ? { input_tokens: res.usage.prompt_tokens, output_tokens: res.usage.completion_tokens } : undefined
};
msg.raw = (content.find(function (b) { return b.type === "text"; }) || {}).text;

return msg;

// Nicht mehr von globalen App-Settings oder einer CMS-Datenbankabfrage
// abhaengig - stattdessen lokale, im Tab selbst einstellbare
// Umgebungsvariablen (siehe Tab-Eigenschaften, Reiter
// "Umgebungsvariablen": AI_PROMPT_ENABLED, AI_SYSTEM_PROMPT).

// Erster Zug: body.message (einzelner String). Ab dem zweiten Zug einer
// agentischen Tool-Use-Konversation schickt das Frontend die komplette
// Historie als body.messages (Array von Anthropic-MessageParam) mit.
const body = msg.req.body ?? {};
const clientMessages = Array.isArray(body.messages) ? body.messages : null;
const message = typeof body.message === "string" ? body.message.trim() : undefined;

if (!clientMessages && !message) {
  msg.statusCode = 400;
  msg.payload = { error: "message oder messages fehlt." };
  return [null, msg];
}

if (!env.get("AI_PROMPT_ENABLED")) {
  msg.statusCode = 400;
  msg.payload = { error: "nicht aktiviert" };
  return [null, msg];
}


// Zeitstempel erzeugen
const now = new Date();
msg.created = now.toISOString(); // → volle UTC-Zeit

msg.message = message;
msg.clientMessages = clientMessages;
msg.tools = Array.isArray(body.tools) ? body.tools : undefined;

msg.locale = body.locale?.trim();
msg.system_prompt = env.get("AI_SYSTEM_PROMPT") || "";

return [msg, null];

// Das Frontend (CAD N'Done, eigener Ursprung) ruft diesen Endpunkt per
// fetch() mit Content-Type: application/json auf - der Browser schickt dem
// eigentlichen POST daher einen OPTIONS-Preflight voraus, der hier
// unabhaengig beantwortet werden muss, sonst blockiert der Browser den POST
// mit einem CORS-Fehler, bevor er ueberhaupt gesendet wird.
msg.statusCode = 204;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
};
return msg;

const cmsg={
    msgno:1000,
    topic:"CHATGPT RETURN",
    functionName:"CHATGPT REQUEST",
    msg:{
        text:"PAYLOAD",
        payload: {
            text:msg.raw,
            question: msg.message
            }
    }
}
msg=cmsg;


return msg;

const cmsg={
    msgno:1000,
    topic:"CHATGPT ERROR",
    functionName:"CHATGPT REQUEST",
    msg:{
        text:"PAYLOAD",
        payload: {
            text:msg.raw,
            question: msg.message
            }
    }
}
msg=cmsg;


return msg;
